-- Biblioteca de modelos de plano da plataforma. GERADO por build_library.py — não edite à mão.
-- Requer a TACO e a base do IBGE importadas. Idempotente (ids estáveis); modelos retirados da biblioteca são apagados.
-- Uso: psql -v ON_ERROR_STOP=1 -f library.sql

begin;

create temp table lib_refs on commit drop as
  select s.code || ':' || f.source_code as ref, f.id::text as id
  from foods f join food_sources s on s.id = f.source_id
  where f.organization_id is null and s.code in ('TACO', 'IBGE');

-- Troca "FONTE:código" pelo id do alimento neste banco (itens e substituições).
create function pg_temp.lib_meals(j jsonb) returns jsonb language sql stable as $$
  select coalesce(jsonb_agg(m.meal || jsonb_build_object('items', (
    select coalesce(jsonb_agg(i.item || jsonb_build_object('foodId', (select id from lib_refs where ref = i.item->>'foodId'))
      || case when i.item ? 'subs' then jsonb_build_object('subs', (
        select coalesce(jsonb_agg(s.sub || jsonb_build_object('foodId', (select id from lib_refs where ref = s.sub->>'foodId')) order by s.n), '[]'::jsonb)
        from jsonb_array_elements(i.item->'subs') with ordinality s(sub, n))) else '{}'::jsonb end order by i.n), '[]'::jsonb)
    from jsonb_array_elements(m.meal->'items') with ordinality i(item, n))) order by m.n), '[]'::jsonb)
  from jsonb_array_elements(j) with ordinality m(meal, n)
$$;

insert into meal_plan_templates (id, organization_id, name, description, tags, mode, targets, meals, guidelines, energy_kcal) values ('214a7d8c-ebfa-544c-8434-efa97bd2e593', null, 'Tradicional brasileiro — 1.200 kcal', 'Modelo base — revisar antes de prescrever. Arroz, feijão, carne magra, verduras e frutas em todas as refeições principais, como no Guia Alimentar. Aprox. 1.201 kcal, 77 g de proteína e 28 g de fibra por dia.', '["biblioteca", "tradicional", "guia alimentar", "1200 kcal"]'::jsonb, 'quantitative', '{"formula": "mifflin", "activity": 1.55, "adjustment": 0, "proteinPerKg": 1.2, "lipidPct": 28, "manualKcal": 1200}'::jsonb, pg_temp.lib_meals('[{"id": "cafe", "name": "Café da manhã", "time": "07:00", "items": [{"key": "lib-cafe-0", "foodId": "TACO:53", "quantityG": 30, "subs": [{"foodId": "TACO:52", "quantityG": 35}, {"foodId": "TACO:533", "quantityG": 80}, {"foodId": "TACO:551", "quantityG": 25}]}, {"key": "lib-cafe-1", "foodId": "TACO:461", "quantityG": 25, "subs": [{"foodId": "TACO:469", "quantityG": 45}, {"foodId": "TACO:488", "quantityG": 45}]}, {"key": "lib-cafe-2", "foodId": "IBGE:7900101-99", "quantityG": 120, "subs": [{"foodId": "TACO:448", "quantityG": 140}]}, {"key": "lib-cafe-3", "foodId": "TACO:471", "quantityG": 50}, {"key": "lib-cafe-4", "foodId": "TACO:226", "quantityG": 125, "subs": [{"foodId": "TACO:235", "quantityG": 150}, {"foodId": "TACO:164", "quantityG": 105}, {"foodId": "TACO:239", "quantityG": 165}]}]}, {"id": "lanche-manha", "name": "Lanche da manhã", "time": "10:00", "items": [{"key": "lib-lanche-manha-0", "foodId": "TACO:182", "quantityG": 70, "subs": [{"foodId": "TACO:222", "quantityG": 120}, {"foodId": "TACO:243", "quantityG": 130}, {"foodId": "TACO:229", "quantityG": 95}]}]}, {"id": "almoco", "name": "Almoço", "time": "12:30", "items": [{"key": "lib-almoco-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-almoco-1", "foodId": "TACO:157", "quantityG": 60}, {"key": "lib-almoco-2", "foodId": "TACO:110", "quantityG": 30}, {"