insert into meal_plan_templates (id, organization_id, name, description, tags, mode, targets, meals, guidelines, energy_kcal) values ('de8df6aa-80c3-584b-9892-e8d5c8bbb544', null, 'Gestante — 2.000 kcal', 'Modelo base — revisar antes de prescrever. Para o 2º e o 3º trimestre: laticínios três vezes ao dia, ferro com vitamina C, folhas verde-escuras e peixe de baixo mercúrio. Aprox. 2.019 kcal, 122 g de proteína e 51 g de fibra por dia.', '["biblioteca", "gestante", "materno-infantil", "2000 kcal"]'::jsonb, 'quantitative', '{"formula": "mifflin", "activity": 1.55, "adjustment": 0, "proteinPerKg": 1.1, "lipidPct": 28, "manualKcal": 2000}'::jsonb, pg_temp.lib_meals('[{"id": "cafe", "name": "Café da manhã", "time": "07:00", "items": [{"key": "lib-cafe-0", "foodId": "TACO:52", "quantityG": 50, "subs": [{"foodId": "TACO:53", "quantityG": 40}, {"foodId": "TACO:533", "quantityG": 110}, {"foodId": "TACO:7", "quantityG": 30}]}, {"key": "lib-cafe-1", "foodId": "TACO:461", "quantityG": 30, "subs": [{"foodId": "TACO:469", "quantityG": 55}, {"foodId": "TACO:488", "quantityG": 55}]}, {"key": "lib-cafe-2", "foodId": "IBGE:7900101-99", "quantityG": 200, "subs": [{"foodId": "TACO:448", "quantityG": 235}]}, {"key": "lib-cafe-3", "foodId": "TACO:226", "quantityG": 150, "subs": [{"foodId": "TACO:235", "quantityG": 180}, {"foodId": "TACO:164", "quantityG": 125}, {"foodId": "TACO:239", "quantityG": 200}]}]}, {"id": "lanche-manha", "name": "Lanche da manhã", "time": "10:00", "items": [{"key": "lib-lanche-manha-0", "foodId": "TACO:448", "quantityG": 170, "subs": [{"foodId": "IBGE:7900101-99", "quantityG": 145}]}, {"key": "lib-lanche-manha-1", "foodId": "TACO:182", "quantityG": 85, "subs": [{"foodId": "TACO:222", "quantityG": 150}, {"foodId": "TACO:243", "quantityG": 155}, {"foodId": "TACO:229", "quantityG": 115}]}]}, {"id": "almoco", "name": "Almoço", "time": "12:30", "items": [{"key": "lib-almoco-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-almoco-1", "foodId": "TACO:157", "quantityG": 60}, {"key": "lib-almoco-2", "foodId": "TACO:110", "quantityG": 30}, {"key": "lib-almoco-3", "foodId": "TACO:3", "quantityG": 125, "subs": [{"foodId": "TACO:1", "quantityG": 130}, {"foodId": "TACO:91", "quantityG": 310}, {"foodId": "TACO:129", "quantityG": 130}]}, {"key": "lib-almoco-4", "foodId": "TACO:561", "quantityG": 135, "subs": [{"foodId": "TACO:567", "quantityG": 135}, {"foodId": "TACO:577", "quantityG": 110}, {"foodId": "IBGE:6302801-99", "quantityG": 55}]}, {"key": "lib-almoco-5", "foodId": "TACO:377", "quantityG": 80, "subs": [{"foodId": "TACO:410", "quantityG": 110}, {"foodId": "TACO:326", "quantityG": 85}, {"foodId": "TACO:313", "quantityG": 115}]}, {"key": "lib-almoco-6", "foodId": "TACO:116", "quantityG": 60}, {"key": "lib-almoco-7", "foodId": "TACO:260", "quantityG": 5}, {"key": "lib-almoco-8", "foodId": "TACO:214", "quantityG": 150, "subs": [{"foodId": "TACO:238", "quantityG": 150}, {"foodId": "TACO:200", "quantityG": 105}, {"foodId": "TACO:207", "quantityG": 110}]}]}, {"id": "lanche-tarde", "name": "Lanche da tarde", "time": "16:00", "items": [{"key": "lib-lanche-tarde-0", "foodId": "TACO:53", "quantityG": 50, "subs": [{"foodId": "TACO:52", "quantityG": 60}, {"foodId": "TACO:533", "quantityG": 135}, {"foodId": "TACO:551", "quantityG": 45}]}, {"key": "lib-lanche-tarde-1", "foodId": "TACO:488", "quantityG": 50, "subs": [{"foodId": "TACO:461", "quantityG": 30}, {"foodId": "TACO:469", "quantityG": 50}]}, {"key": "lib-lanche-tarde-2", "foodId": "TACO:200", "quantityG": 120, "subs": [{"foodId": "TACO:214", "quantityG": 175}, {"foodId": "TACO:207", "quantityG": 125}]}]}, {"id": "jantar", "name": "Jantar", "time": "19:30", "items": [{"key": "lib-jantar-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-jantar-1", "foodId": "TACO:97", "quantityG": 50}, {"key": "lib-jantar-2", "foodId": "TACO:3", "quantityG": 95, "subs": [{"foodId": "TACO:1", "quantityG": 100}, {"foodId": "TACO:91", "quantityG": 235}, {"foodId": "TACO:129", "quantityG": 95}]}, {"key": "lib-jantar-3", "foodId": "TACO:561", "quantityG": 100, "subs": [{"foodId": "TACO:567", "quantityG": 100}, {"foodId": "TACO:577", "quantityG": 80}, {"foodId": "IBGE:6302801-99", "quantityG": 40}]}, {"key": "lib-jantar-4", "foodId": "TACO:318", "quantityG": 80, "subs": [{"foodId": "TACO:313", "quantityG": 85}, {"foodId": "TACO:317", "quantityG": 55}]}, {"key": "lib-jantar-5", "foodId": "TACO:100", "quantityG": 80}, {"key": "lib-jantar-6", "foodId": "TACO:260", "quantityG": 5}]}, {"id": "ceia", "name": "Ceia", "time": "21:30", "items": [{"key": "lib-ceia-0", "foodId": "IBGE:7900101-99", "quantityG": 150, "subs": [{"foodId": "TACO:448", "quantityG": 175}]}, {"key": "lib-ceia-1", "foodId": "TACO:7", "quantityG": 15}]}]'::jsonb), '• Suplementos (ácido fólico, ferro e outros) somente conforme prescrição e acompanhamento do pré-natal.
• Carnes, peixes e ovos sempre bem cozidos; nada de leite cru ou queijo de leite não pasteurizado; lave bem frutas e verduras.
• Prefira peixes de baixo mercúrio (sardinha, pescada, tilápia) e evite os grandes predadores (cação, atum fresco, peixe-espada).
• Sem bebida alcoólica. Café com moderação (até 2 xícaras pequenas por dia).
• Fracione em 6 refeições se houver enjoo ou azia; beba água ao longo do dia.
• Modelo base da biblioteca Rafanutri: ajuste quantidades, alimentos e horários ao paciente antes de publicar.
• As quantidades são do alimento pronto para consumo (cozido, grelhado ou cru, conforme o nome). As substituições de cada item têm a mesma energia.', 2019.0)
