insert into meal_plan_templates (id, organization_id, name, description, tags, mode, targets, meals, guidelines, energy_kcal) values ('4b2b72bf-f523-5e41-8e16-e929292b9257', null, 'Pessoa idosa — 1.600 kcal', 'Modelo base — revisar antes de prescrever. Proteína distribuída nas refeições, laticínios três vezes ao dia, preparações macias, fibra e boa hidratação. Aprox. 1.601 kcal, 100 g de proteína e 26 g de fibra por dia.', '["biblioteca", "idoso", "pessoa idosa", "1600 kcal"]'::jsonb, 'quantitative', '{"formula": "mifflin", "activity": 1.55, "adjustment": 0, "proteinPerKg": 1.2, "lipidPct": 28, "manualKcal": 1600}'::jsonb, pg_temp.lib_meals('[{"id": "cafe", "name": "Café da manhã", "time": "07:00", "items": [{"key": "lib-cafe-0", "foodId": "TACO:53", "quantityG": 45, "subs": [{"foodId": "TACO:52", "quantityG": 55}, {"foodId": "TACO:533", "quantityG": 120}, {"foodId": "TACO:551", "quantityG": 40}]}, {"key": "lib-cafe-1", "foodId": "TACO:488", "quantityG": 45, "subs": [{"foodId": "TACO:461", "quantityG": 25}, {"foodId": "TACO:469", "quantityG": 45}]}, {"key": "lib-cafe-2", "foodId": "IBGE:7900101-99", "quantityG": 190, "subs": [{"foodId": "TACO:448", "quantityG": 225}]}, {"key": "lib-cafe-3", "foodId": "TACO:226", "quantityG": 145, "subs": [{"foodId": "TACO:235", "quantityG": 175}, {"foodId": "TACO:164", "quantityG": 120}, {"foodId": "TACO:239", "quantityG": 195}]}]}, {"id": "lanche-manha", "name": "Lanche da manhã", "time": "10:00", "items": [{"key": "lib-lanche-manha-0", "foodId": "TACO:448", "quantityG": 160, "subs": [{"foodId": "IBGE:7900101-99", "quantityG": 135}]}, {"key": "lib-lanche-manha-1", "foodId": "TACO:182", "quantityG": 80, "subs": [{"foodId": "TACO:222", "quantityG": 140}, {"foodId": "TACO:243", "quantityG": 150}, {"foodId": "TACO:229", "quantityG": 110}]}]}, {"id": "almoco", "name": "Almoço", "time": "12:30", "items": [{"key": "lib-almoco-0", "foodId": "TACO:78", "quantityG": 20}, {"key": "lib-almoco-1", "foodId": "TACO:157", "quantityG": 50}, {"key": "lib-almoco-2", "foodId": "TACO:3", "quantityG": 95, "subs": [{"foodId": "TACO:1", "quantityG": 100}, {"foodId": "TACO:91", "quantityG": 235}, {"foodId": "TACO:129", "quantityG": 95}]}, {"key": "lib-almoco-3", "foodId": "TACO:561", "quantityG": 110, "subs": [{"foodId": "TACO:567", "quantityG": 110}, {"foodId": "TACO:577", "quantityG": 90}, {"foodId": "IBGE:6302801-99", "quantityG": 45}]}, {"key": "lib-almoco-4", "foodId": "TACO:326", "quantityG": 85, "subs": [{"foodId": "TACO:377", "quantityG": 80}, {"foodId": "TACO:410", "quantityG": 115}]}, {"key": "lib-almoco-5", "foodId": "TACO:64", "quantityG": 90}, {"key": "lib-almoco-6", "foodId": "TACO:260", "quantityG": 4}, {"key": "lib-almoco-7", "foodId": "TACO:214", "quantityG": 145, "subs": [{"foodId": "TACO:238", "quantityG": 145}, {"foodId": "TACO:200", "quantityG": 100}, {"foodId": "TACO:207", "quantityG": 105}]}]}, {"id": "lanche-tarde", "name": "Lanche da tarde", "time": "16:00", "items": [{"key": "lib-lanche-tarde-0", "foodId": "IBGE:7900101-99", "quantityG": 140, "subs": [{"foodId": "TACO:448", "quantityG": 165}]}, {"key": "lib-lanche-tarde-1", "foodId": "TACO:7", "quantityG": 18}, {"key": "lib-lanche-tarde-2", "foodId": "TACO:222", "quantityG": 105, "subs": [{"foodId": "TACO:243", "quantityG": 110}, {"foodId": "TACO:182", "quantityG": 60}, {"foodId": "TACO:200", "quantityG": 110}]}]}, {"id": "jantar", "name": "Jantar", "time": "19:30", "items": [{"key": "lib-jantar-0", "foodId": "TACO:110", "quantityG": 40}, {"key": "lib-jantar-1", "foodId": "TACO:91", "quantityG": 130}, {"key": "lib-jantar-2", "foodId": "TACO:410", "quantityG": 85, "subs": [{"foodId": "TACO:377", "quantityG": 60}, {"foodId": "TACO:313", "quantityG": 90}, {"foodId": "TACO:488", "quantityG": 95}]}, {"key": "lib-jantar-3", "foodId": "TACO:112", "quantityG": 90}, {"key": "lib-jantar-4", "foodId": "TACO:260", "quantityG": 4}]}, {"id": "ceia", "name": "Ceia", "time": "21:30", "items": [{"key": "lib-ceia-0", "foodId": "TACO:448", "quantityG": 115, "subs": [{"foodId": "IBGE:7900101-99", "quantityG": 100}]}]}]'::jsonb), '• Uma fonte de proteína (ovo, leite, iogurte, carne, frango, peixe ou feijão) em cada refeição ajuda a manter a massa muscular.
• Beba água mesmo sem sede (a sensação de sede diminui com a idade): deixe uma garrafa à vista.
• Prefira preparações macias (carne moída ou desfiada, legumes bem cozidos) se houver dificuldade para mastigar.
• Laticínios três vezes ao dia para o cálcio; sol pela manhã ajuda na vitamina D (avalie a suplementação).
• Cuidado com o sal e com chás ou suplementos sem orientação, por causa dos medicamentos.
• Modelo base da biblioteca Rafanutri: ajuste quantidades, alimentos e horários ao paciente antes de publicar.
• As quantidades são do alimento pronto para consumo (cozido, grelhado ou cru, conforme o nome). As substituições de cada item têm a mesma energia.', 1601.3)
