insert into meal_plan_templates (id, organization_id, name, description, tags, mode, targets, meals, guidelines, energy_kcal) values ('99ed8cf9-5590-5d74-9d6c-b1ee56126404', null, 'Esportivo — hipertrofia — 2.200 kcal', 'Modelo base — revisar antes de prescrever. Proteína de 1,6 a 2,2 g/kg distribuída em 5 a 6 refeições, carboidrato antes e depois do treino e superávit calórico moderado. Aprox. 2.227 kcal, 150 g de proteína e 32 g de fibra por dia.', '["biblioteca", "esportivo", "hipertrofia", "ganho de massa", "2200 kcal"]'::jsonb, 'quantitative', '{"formula": "mifflin", "activity": 1.55, "adjustment": 0, "proteinPerKg": 1.8, "lipidPct": 25, "manualKcal": 2200}'::jsonb, pg_temp.lib_meals('[{"id": "cafe", "name": "Café da manhã", "time": "07:00", "items": [{"key": "lib-cafe-0", "foodId": "TACO:53", "quantityG": 40, "subs": [{"foodId": "TACO:52", "quantityG": 45}, {"foodId": "TACO:533", "quantityG": 105}, {"foodId": "TACO:551", "quantityG": 35}]}, {"key": "lib-cafe-1", "foodId": "TACO:488", "quantityG": 85, "subs": [{"foodId": "TACO:461", "quantityG": 45}, {"foodId": "TACO:469", "quantityG": 90}]}, {"key": "lib-cafe-2", "foodId": "TACO:461", "quantityG": 25, "subs": [{"foodId": "TACO:469", "quantityG": 45}, {"foodId": "TACO:488", "quantityG": 45}]}, {"key": "lib-cafe-3", "foodId": "IBGE:7900101-99", "quantityG": 180, "subs": [{"foodId": "TACO:448", "quantityG": 210}]}, {"key": "lib-cafe-4", "foodId": "TACO:182", "quantityG": 80, "subs": [{"foodId": "TACO:222", "quantityG": 140}, {"foodId": "TACO:243", "quantityG": 150}, {"foodId": "TACO:229", "quantityG": 110}]}]}, {"id": "lanche-manha", "name": "Lanche da manhã", "time": "10:00", "items": [{"key": "lib-lanche-manha-0", "foodId": "TACO:448", "quantityG": 150, "subs": [{"foodId": "IBGE:7900101-99", "quantityG": 125}]}, {"key": "lib-lanche-manha-1", "foodId": "TACO:7", "quantityG": 25}, {"key": "lib-lanche-manha-2", "foodId": "TACO:589", "quantityG": 8, "subs": [{"foodId": "TACO:597", "quantityG": 8}, {"foodId": "TACO: