TACO:7", "quantityG": 20}, {"key": "lib-pos-treino-2", "foodId": "TACO:488", "quantityG": 55, "subs": [{"foodId": "TACO:461", "quantityG": 30}, {"foodId": "TACO:469", "quantityG": 55}]}]}, {"id": "jantar", "name": "Jantar", "time": "21:00", "items": [{"key": "lib-jantar-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-jantar-1", "foodId": "TACO:157", "quantityG": 60}, {"key": "lib-jantar-2", "foodId": "TACO:88", "quantityG": 220, "subs": [{"foodId": "TACO:129", "quantityG": 135}, {"foodId": "IBGE:6400501-2", "quantityG": 170}, {"foodId": "TACO:91", "quantityG": 325}]}, {"key": "lib-jantar-3", "foodId": "TACO:377", "quantityG": 140, "subs": [{"foodId": "TACO:410", "quantityG": 195}, {"foodId": "TACO:326", "quantityG": 145}, {"foodId": "TACO:313", "quantityG": 200}]}, {"key": "lib-jantar-4", "foodId": "TACO:72", "quantityG": 80}, {"key": "lib-jantar-5", "foodId": "TACO:260", "quantityG": 7}]}]'::jsonb), '• Proteína em todas as refeições (ovos, laticínios, carnes, frango, peixe, leguminosas), em porções de 20 a 40 g de proteína.
• Pré-treino (1 a 2 h antes): carboidrato de fácil digestão com pouca gordura e fibra.
• Pós-treino: proteína com carboidrato em até 2 horas, junto da refeição seguinte se for perto.
• Hidratação: beba água ao longo do dia e reponha o que perder no treino (pese-se antes e depois para estimar).
• Suplementos (whey, creatina e outros) só com indicação e prescrição individual.
• Modelo base da biblioteca Rafanutri: ajuste quantidades, alimentos e horários ao paciente antes de publicar.
• As quantidades são do alimento pronto para consumo (cozido, grelhado ou cru, conforme o nome). As substituições de cada item têm a mesma energia.', 2809.6)
