insert into meal_plan_templates (id, organization_id, name, description, tags, mode, targets, meals, guidelines, energy_kcal) values ('4c14ab87-c2d1-54dd-93e7-a1ef6b834d63', null, 'Esportivo — endurance (corrida, ciclismo) — 2.200 kcal', 'Modelo base — revisar antes de prescrever. Carboidrato alto (5 a 8 g/kg conforme o volume de treino), proteína moderada e refeições antes e depois das sessões. Aprox. 2.183 kcal, 94 g de proteína e 31 g de fibra por dia.', '["biblioteca", "esportivo", "endurance", "corrida", "ciclismo", "2200 kcal"]'::jsonb, 'quantitative', '{"formula": "mifflin", "activity": 1.55, "adjustment": 0, "proteinPerKg": 1.4, "lipidPct": 25, "manualKcal": 2200}'::jsonb, pg_temp.lib_meals('[{"id": "cafe", "name": "Café da manhã", "time": "07:00", "items": [{"key": "lib-cafe-0", "foodId": "TACO:53", "quantityG": 60, "subs": [{"foodId": "TACO:52", "quantityG": 70}, {"foodId": "TACO:533", "quantityG": 160}, {"foodId": "TACO:551", "quantityG": 50}]}, {"key": "lib-cafe-1", "foodId": "TACO:507", "quantityG": 13}, {"key": "lib-cafe-2", "foodId": "TACO:461", "quantityG": 25, "subs": [{"foodId": "TACO:469", "quantityG": 45}, {"foodId": "TACO:488", "quantityG": 45}]}, {"key": "lib-cafe-3", "foodId": "IBGE:7900101-99", "quantityG": 185, "subs": [{"foodId": "TACO:448", "quantityG": 220}]}, {"key": "lib-cafe-4", "foodId": "TACO:182", "quantityG": 80, "subs": [{"foodId": "TACO:222", "quantityG": 140}, {"foodId": "TACO:243", "quantityG": 150}, {"foodId": "TACO:229", "quantityG": 110}]}, {"key": "lib-cafe-5", "foodId": "TACO:7", "quantityG": 17}]}, {"id": "lanche-manha", "name": "Lanche da manhã", "time": "10:00", "items": [{"key": "lib-lanche-manha-0", "foodId": "TACO:448", "quantityG": 155, "subs": [{"foodId": "IBGE:7900101-99", "quantityG": 130}]}, {"key": "lib-lanche-manha-1", "foodId": "TACO:229", "quantityG": 115, "subs": [{"foodId": "TACO:182", "quantityG": 85}, {"foodId": "TACO:226", "quantityG": 205}]}]}, {"id": "almoco", "name": "Almoço", "time": "12:30", "items": [{"key": "lib-almoco-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-almoco-1", "foodId": "TACO:157", "quantityG": 60}, {"key": "lib-almoco-2", "foodId": "TACO:110", "quantityG": 30}, {"key": "lib-almoco-3", "foodId": "TACO:3", "quantityG": 170, "subs": [{"foodId": "TACO:1", "quantityG": 175}, {"foodId": "TACO:91", "quantityG": 420}, {"foodId": "TACO:129", "quantityG": 175}]}, {"key": "lib-almoco-4", "foodId": "TACO:561", "quantityG": 105, "subs": [{"foodId": "TACO:567", "quantityG": 105}, {"foodId": "TACO:577", "quantityG": 85}, {"foodId": "IBGE:6302801-99", "quantityG": 40}]}, {"key": "lib-almoco-5", "foodId": "TACO:410", "quantityG": 90, "subs": [{"foodId": "TACO:377", "quantityG": 65}, {"foodId": "TACO:313", "quantityG": 95}, {"foodId": "TACO:488", "quantityG": 100}]}, {"key": "lib-almoco-6", "foodId": "TACO:110", "quantityG": 50}, {"key": "lib-almoco-7", "foodId": "TACO:260", "quantityG": 5}, {"key": "lib-almoco-8", "foodId": "TACO:214", "quantityG": 140, "subs": [{"foodId": "TACO:238", "quantityG": 140}, {"foodId": "TACO:200", "quantityG": 95}, {"foodId": "TACO:207", "quantityG": 100}]}]}, {"id": "pre-treino", "name": "Pré-treino", "time": "17:00", "items": [{"key": "lib-pre-treino-0", "foodId": "TACO:551", "quantityG": 50, "subs": [{"foodId": "TACO:533", "quantityG": 155}, {"foodId": "TACO:53", "quantityG": 60}]}, {"key": "lib-pre-treino-1", "foodId": "TACO:182", "quantityG": 80, "subs": [{"foodId": "TACO:222", "quantityG": 140}, {"foodId": "TACO:243", "quantityG": 150}, {"foodId": "TACO:229", "quantityG": 110}]}]}, {"id": "pos-treino", "name": "Pós-treino", "time": "19:00", "items": [{"key": "lib-pos-treino-0", "foodId": "IBGE:7900101-99", "quantityG": 230, "subs": [{"foodId": "TACO:448", "quantityG": 270}]}, {"key": "lib-pos-treino-1", "foodId": "TACO:53", "quantityG": 40, "subs": [{"foodId": "TACO:52", "quantityG": 45}, {"foodId": "TACO:533", "quantityG": 105}, {"foodId": "TACO:551", "quantityG": 35}]}, {"key": "lib-pos-treino-2", "foodId": "TACO:507", "quantityG": 8}]}, {"id": "jantar", "name": "Jantar", "time": "21:00", "items": [{"key": "lib-jantar-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-jantar-1", "foodId": "TACO:157", "quantityG": 60}, {"key": "lib-jantar-2", "foodId": "TACO:542", "quantityG": 250}, {"key": "lib-jantar-3", "foodId": "TACO:100", "quantityG": 80}, {"key": "lib-jantar-4", "foodId": "TACO:260", "quantityG": 4}]}]'::jsonb), '• Ajuste o carboidrato ao treino do dia: mais nos dias longos ou intensos, menos nos dias leves ou de descanso.
• Em treinos acima de 60 a 90 minutos, use carboidrato durante a atividade (30 a 60 g por hora: gel, bebida esportiva, banana, rapadura).
• Pré-treino com pouca fibra e gordura para evitar desconforto gastrointestinal; teste as estratégias nos treinos, nunca na prova.
• Reidrate-se após o treino com cerca de 1,5 L para cada kg perdido, com sódio se o suor for intenso.
• Ferro, cálcio e vitamina D merecem atenção, principalmente em mulheres atletas.
• Modelo base da biblioteca Rafanutri: ajuste quantidades, alimentos e horários ao paciente antes de publicar.
• As quantidades são do alimento pronto para consumo (cozido, grelhado ou cru, conforme o nome). As substituições de cada item têm a mesma energia.', 2183.3)
