insert into meal_plan_templates (id, organization_id, name, description, tags, mode, targets, meals, guidelines, energy_kcal) values ('98ce3770-d33c-55ad-96ea-255c46bd2c56', null, 'Colesterol e triglicerídeos (dislipidemia) — 2.000 kcal', 'Modelo base — revisar antes de prescrever. Pouca gordura saturada e trans, aveia e leguminosas (fibra solúvel), peixe, azeite e oleaginosas; pouco açúcar e álcool. Aprox. 1.986 kcal, 130 g de proteína e 47 g de fibra por dia.', '["biblioteca", "dislipidemia", "colesterol", "triglicerídeos", "cardiovascular", "2000 kcal"]'::jsonb, 'quantitative', '{"formula": "mifflin", "activity": 1.55, "adjustment": 0, "proteinPerKg": 1.1, "lipidPct": 28, "manualKcal": 2000}'::jsonb, pg_temp.lib_meals('[{"id": "cafe", "name": "Café da manhã", "time": "07:00", "items": [{"key": "lib-cafe-0", "foodId": "TACO:52", "quantityG": 70, "subs": [{"foodId": "TACO:53", "quantityG": 60}, {"foodId": "TACO:533", "quantityG": 155}, {"foodId": "TACO:7", "quantityG": 45}]}, {"key": "lib-cafe-1", "foodId": "TACO:469", "quantityG": 35}, {"key": "lib-cafe-2", "foodId": "IBGE:7903601-99", "quantityG": 235, "subs": [{"foodId": "TACO:449", "quantityG": 195}]}, {"key": "lib-cafe-3", "foodId": "TACO:226", "quantityG": 170, "subs": [{"foodId": "TACO:235", "quantityG": 205}, {"foodId": "TACO:164", "quantityG": 140}, {"foodId": "TACO:239", "quantityG": 225}]}]}, {"id": "lanche-manha", "name": "Lanche da manhã", "time": "10:00", "items": [{"key": "lib-lanche-manha-0", "foodId": "TACO:222", "quantityG": 145, "subs": [{"foodId": "TACO:243", "quantityG": 155}, {"foodId": "TACO:182", "quantityG": 85}, {"foodId": "TACO:200", "quantityG": 150}]}, {"key": "lib-lanche-manha-1", "foodId": "TACO:597", "quantityG": 14, "subs": [{"foodId": "TACO:589", "quantityG": 13}, {"foodId": "TACO:557", "quantityG": 16}]}]}, {"id": "almoco", "name": "Almoço", "time": "12:30", "items": [{"key": "lib-almoco-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-almoco-1", "foodId": "TACO:157", "quan