insert into meal_plan_templates (id, organization_id, name, description, tags, mode, targets, meals, guidelines, energy_kcal) values ('3c9d1f6b-3689-5752-afe0-ca91c1d6cb6a', null, 'Transtornos alimentares — alimentação regular (anorexia e bulimia)', 'Modelo base — revisar antes de prescrever. Plano qualitativo, sem calorias nem gramas para o paciente: três refeições e três lanches em horários fixos, todos os grupos alimentares e sem alimentos proibidos. Referência para a equipe: cerca de 2.201 kcal; o paciente não vê números.', '["biblioteca", "transtorno alimentar", "anorexia", "bulimia", "qualitativo"]'::jsonb, 'qualitative', '{"formula": "mifflin", "activity": 1.55, "adjustment": 0, "proteinPerKg": 1.2, "lipidPct": 30, "manualKcal": 2200}'::jsonb, pg_temp.lib_meals('[{"id": "cafe", "name": "Café da manhã", "time": "07:00", "items": [{"key": "lib-cafe-0", "foodId": "TACO:53", "quantityG": 45, "subs": [{"foodId": "TACO:52", "quantityG": 55}, {"foodId": "TACO:533", "quantityG": 120}, {"foodId": "TACO:551", "quantityG": 40}]}, {"key": "lib-cafe-1", "foodId": "TACO:468", "quantityG": 19, "subs": [{"foodId": "TACO:461", "quantityG": 18}, {"foodId": "TACO:469", "quantityG": 35}]}, {"key": "lib-cafe-2", "foodId": "IBGE:7900101-99", "quantityG": 195, "subs": [{"foodId": "TACO:448", "quantityG": 230}]}, {"key": "lib-cafe-3", "foodId": "TACO:182", "quantityG": 85, "subs": [{"foodId": "TACO:222", "quantityG": 150}, {"foodId": "TACO:243", "quantityG": 155}, {"foodId": "TACO:229", "quantityG": 115}]}]}, {"id": "lanche-manha", "name": "Lanche da manhã", "time": "10:00", "items": [{"key": "lib-lanche-manha-0", "foodId": "TACO:448", "quantityG": 165, "subs": [{"foodId": "IBGE:7900101-99", "quantityG": 140}]}, {"key": "lib-lanche-manha-1", "foodId": "TACO:7", "quantityG": 19}]}, {"id": "almoco", "name": "Almoço", "time": "12:30", "items": [{"key": "lib-almoco-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-almoco-1", "foodId": "TACO:157", "quantityG": 60}, {"key": "lib-almoco-2", "foodId": "TACO:110", "quantityG": 30}, {"key": "lib-almoco-3", "foodId": "TACO:3", "quantityG": 140, "subs": [{"foodId": "TACO:1", "quantityG": 145}, {"foodId": "TACO:91", "quantityG": 345}, {"foodId": "TACO:129", "quantityG": 145}]}, {"key": "lib-almoco-4", "foodId": "TACO:561", "quantityG": 115, "subs": [{"foodId": "TACO:567", "quantityG": 115}, {"foodId": "TACO:577", "quantityG": 95}, {"foodId": "IBGE:6302801-99", "quantityG": 45}]}, {"key": "lib-almoco-5", "foodId": "TACO:377", "quantityG": 95, "subs": [{"foodId": "TACO:410", "quantityG": 130}, {"foodId": "TACO:326", "quantityG": 100}, {"foodId": "TACO:313", "quantityG": 135}]}, {"key": "lib-almoco-6", "foodId": "TACO:72", "quantityG": 70}, {"key": "lib-almoco-7", "foodId": "TACO:260", "quantityG": 8}, {"key": "lib-almoco-8", "foodId": "TACO:214", "quantityG": 145, "subs": [{"foodId": "TACO:238", "quantityG": 145}, {"foodId": "TACO:200", "quantityG": 100}, {"foodId": "TACO:207", "quantityG": 105}]}]}, {"id": "lanche-tarde", "name": "Lanche da tarde", "time": "16:00", "items": [{"key": "lib-lanche-tarde-0", "foodId": "TACO:53", "quantityG": 45, "subs": [{"foodId": "TACO:52", "quantityG": 55}, {"foodId": "TACO:533", "quantityG": 120}, {"foodId": "TACO:551", "quantityG": 40}]}, {"key": "lib-lanche-tarde-1", "foodId": "TACO:461", "quantityG": 30, "subs": [{"foodId": "TACO:469", "quantityG": 55}, {"foodId": "TACO:488", "quantityG": 55}]}, {"key": "lib-lanche-tarde-2", "foodId": "TACO:222", "quantityG": 125, "subs": [{"foodId": "TACO:243", "quantityG": 130}, {"foodId": "TACO:182", "quantityG": 70}, {"foodId": "TACO:200", "quantityG": 130}]}, {"key": "lib-lanche-tarde-3", "foodId": "TACO:16", "quantityG": 40}]}, {"id": "jantar", "name": "Jantar", "time": "19:30", "items": [{"key": "lib-jantar-0", "foodId": "TACO:542", "quantityG": 235}, {"key": "lib-jantar-1", "foodId": "TACO:100", "quantityG": 70}, {"key": "lib-jantar-2", "foodId": "TACO:260", "quantityG": 5}]}, {"id": "ceia", "name": "Ceia", "time": "21:30", "items": [{"key": "lib-ceia-0", "foodId": "IBGE:7900101-99", "quantityG": 195, "subs": [{"foodId": "TACO:448", "quantityG": 230}]}, {"key": "lib-ceia-1", "foodId": "TACO:8", "quantityG": 25, "subs": [{"foodId": "TACO:13", "quantityG": 25}, {"foodId": "TACO:53", "quantityG": 35}]}]}]'::jsonb), '• Coma em todos os horários combinados, mesmo sem fome: a regularidade é a base do tratamento.
• Nenhum alimento é proibido. Os alimentos que dão medo entram aos poucos, combinados com o seu nutricionista.
• Evite contar calorias, pesar-se em casa e comparar o seu prato com o de outras pessoas.
• Depois de comer, fique com alguém ou faça uma atividade tranquila; se vier vontade de compensar, registre e converse na próxima consulta.
• O plano faz parte do tratamento com a equipe (psicólogo, psiquiatra e médico). Sinais de alerta (desmaio, palpitação, vômitos frequentes): procure atendimento.
• Modelo base da biblioteca Rafanutri: ajuste quantidades, alimentos e horários ao paciente antes de publicar.
• As quantidades são do alimento pronto para consumo (cozido, grelhado ou cru, conforme o nome). As substituições de cada item têm a mesma energia.', null)
