insert into meal_plan_templates (id, organization_id, name, description, tags, mode, targets, meals, guidelines, energy_kcal) values ('d9b6f008-6bed-505c-8290-164b6949234c', null, 'Transtornos alimentares — compulsão alimentar', 'Modelo base — revisar antes de prescrever. Plano qualitativo e sem restrição: refeições regulares para não chegar com muita fome, com proteína, fibra e espaço para alimentos prazerosos. Referência para a equipe: cerca de 2.003 kcal; o paciente não vê números.', '["biblioteca", "transtorno alimentar", "compulsão alimentar", "qualitativo"]'::jsonb, 'qualitative', '{"formula": "mifflin", "activity": 1.55, "adjustment": 0, "proteinPerKg": 1.2, "lipidPct": 30, "manualKcal": 2000}'::jsonb, pg_temp.lib_meals('[{"id": "cafe", "name": "Café da manhã", "time": "07:00", "items": [{"key": "lib-cafe-0", "foodId": "TACO:52", "quantityG": 45, "subs": [{"foodId": "TACO:53", "quantityG": 40}, {"foodId": "TACO:533", "quantityG": 100}, {"foodId": "TACO:7", "quantityG": 30}]}, {"key": "lib-cafe-1", "foodId": "TACO:488", "quantityG": 50, "subs": [{"foodId": "TACO:461", "quantityG": 30}, {"foodId": "TACO:469", "quantityG": 50}]}, {"key": "lib-cafe-2", "foodId": "IBGE:7900101-99", "quantityG": 195, "subs": [{"foodId": "TACO:448", "quantityG": 230}]}, {"key": "lib-cafe-3", "foodId": "TACO:226", "quantityG": 145, "subs": [{"foodId": "TACO:235", "quantityG": 175}, {"foodId": "TACO:164", "quantityG": 120}, {"foodId": "TACO:239", "quantityG": 195}]}]}, {"id": "lanche-manha", "name": "Lanche da manhã", "time": "10:00", "items": [{"key": "lib-lanche-manha-0", "foodId": "TACO:448", "quantityG": 165, "subs": [{"foodId": "IBGE:7900101-99", "quantityG": 140}]}, {"key": "lib-lanche-manha-1", "foodId": "TACO:182", "quantityG": 85, "subs": [{"foodId": "TACO:222", "quantityG": 150}, {"foodId": "TACO:243", "quantityG": 155}, {"foodId": "TACO:229", "quantityG": 115}]}]}, {"id": "almoco", "name": "Almoço", "time": "12:30", "items": [{"key": "lib-almoco-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-almoco-1", "foodId": "TACO:157", "quantityG": 60}, {"key": "lib-almoco-2", "foodId": "TACO:110", "quantityG": 30}, {"key": "lib-almoco-3", "foodId": "TACO:3", "quantityG": 120, "subs": [{"foodId": "TACO:1", "quantityG": 125}, {"foodId": "TACO:91", "quantityG": 295}, {"foodId": "TACO:129", "quantityG": 125}]}, {"key": "lib-almoco-4", "foodId": "TACO:561", "quantityG": 115, "subs": [{"foodId": "TACO:567", "quantityG": 115}, {"foodId": "TACO:577", "quantityG": 95}, {"foodId": "IBGE:6302801-99", "quantityG": 45}]}, {"key": "lib-almoco-5", "foodId": "TACO:410", "quantityG": 95, "subs": [{"foodId": "TACO:377", "quantityG": 70}, {"foodId": "TACO:313", "quantityG": 100}, {"foodId": "TACO:488", "quantityG": 105}]}, {"key": "lib-almoco-6", "foodId": "TACO:100", "quantityG": 80}, {"key": "lib-almoco-7", "foodId": "TACO:260", "quantityG": 6}, {"key": "lib-almoco-8", "foodId": "TACO:214", "quantityG": 145, "subs": [{"foodId": "TACO:238", "quantityG": 145}, {"foodId": "TACO:200", "quantityG": 100}, {"foodId": "TACO:207", "quantityG": 105}]}]}, {"id": "lanche-tarde", "name": "Lanche da tarde", "time": "16:00", "items": [{"key": "lib-lanche-tarde-0", "foodId": "TACO:53", "quantityG": 45, "subs": [{"foodId": "TACO:52", "quantityG": 55}, {"foodId": "TACO:533", "quantityG": 120}, {"foodId": "TACO:551", "quantityG": 40}]}, {"key": "lib-lanche-tarde-1", "foodId": "TACO:461", "quantityG": 30, "subs": [{"foodId": "TACO:469", "quantityG": 55}, {"foodId": "TACO:488", "quantityG": 55}]}, {"key": "lib-lanche-tarde-2", "foodId": "TACO:495", "quantityG": 19}, {"key": "lib-lanche-tarde-3", "foodId": "TACO:222", "quantityG": 125, "subs": [{"foodId": "TACO:243", "quantityG": 130}, {"foodId": "TACO:182", "quantityG": 70}, {"foodId": "TACO:200", "quantityG": 130}]}]}, {"id": "jantar", "name": "Jantar", "time": "19:30", "items": [{"key": "lib-jantar-0", "foodId": "TACO:78", "quantityG": 30}, {"key": "lib-jantar-1", "foodId": "TACO:157", "quantityG": 60}, {"key": "lib-jantar-2", "foodId": "TACO:3", "quantityG": 105, "subs": [{"foodId": "TACO:1", "quantityG": 110}, {"foodId": "TACO:91", "quantityG": 260}, {"foodId": "TACO:129", "quantityG": 110}]}, {"key": "lib-jantar-3", "foodId": "TACO:561", "quantityG": 85, "subs": [{"foodId": "TACO:567", "quantityG": 85}, {"foodId": "TACO:577", "quantityG": 70}, {"foodId": "IBGE:6302801-99", "quantityG": 35}]}, {"key": "lib-jantar-4", "foodId": "TACO:377", "quantityG": 85, "subs": [{"foodId": "TACO:410", "quantityG": 115}, {"foodId": "TACO:326", "quantityG": 90}, {"foodId": "TACO:313", "quantityG": 120}]}, {"key": "lib-jantar-5", "foodId": "TACO:72", "quantityG": 80}, {"key": "lib-jantar-6", "foodId": "TACO:260", "quantityG": 5}]}, {"id": "ceia", "name": "Ceia", "time": "21:30", "items": [{"key": "lib-ceia-0", "foodId": "TACO:61", "quantityG": 19}]}]'::jsonb), '• Não pule refeições: ficar muitas horas sem comer aumenta o risco de episódios de compulsão.
• Sem dieta restritiva e sem alimentos proibidos; doces e petiscos entram de forma planejada.
• Coma sentado, sem telas, prestando atenção ao sabor e aos sinais de fome e saciedade.
• Registre como se sentiu antes e depois das refeições e dos episódios, sem julgamento, para conversar na consulta.
• O plano faz parte do tratamento com a equipe de saúde mental.
• Modelo base da biblioteca Rafanutri: ajuste quantidades, alimentos e horários ao paciente antes de publicar.
• As quantidades são do alimento pronto para consumo (cozido, grelhado ou cru, conforme o nome). As substituições de cada item têm a mesma energia.', null)
